const items = $input.all();

const categories = {
  ai_ml: ['ai', 'artificial intelligence', 'machine learning', 'deep learning', 'llm', 'gpt', 'claude', 'gemini', 'neural', 'transformer', 'diffusion', 'generative', 'rag', 'embedding', 'vector', 'fine-tun', 'inference', 'agent', 'openai', 'anthropic', 'mistral', 'llama', 'prompt', 'chatgpt'],
  cloud: ['cloud', 'aws', 'azure', 'gcp', 'google cloud', 'kubernetes', 'k8s', 'docker', 'serverless', 'lambda', 'devops', 'terraform', 'microservice', 'container', 'ec2', 's3', 'vpc', 'ci/cd'],
  ai_tools: ['tool', 'cursor', 'copilot', 'v0', 'replit', 'vercel', 'hugging face', 'langchain', 'langgraph', 'crewai', 'autogen', 'ollama', 'lmstudio', 'comfyui', 'stable diffusion'],
  web_dev: ['javascript', 'typescript', 'react', 'nextjs', 'python', 'rust', 'api', 'web', 'frontend', 'backend', 'fullstack', 'framework', 'database', 'postgresql', 'redis', 'graphql']
};

const normalized = [];

for (const item of items) {
  const data = item.json;

  if (data.hits && Array.isArray(data.hits)) {
    for (const hit of data.hits) {
      if (hit.title && (hit.url || hit.objectID)) {
        normalized.push({
          title: hit.title.substring(0, 100),
          url: hit.url || `https://news.ycombinator.com/item?id=${hit.objectID}`,
          description: (hit.story_text || '').replace(/<[^>]*>/g, '').substring(0, 120),
          source: 'HackerNews',
          points: hit.points || 0
        });
      }
    }
  } else if (data.results && Array.isArray(data.results)) {
    for (const paper of data.results) {
      if (paper.title) {
        normalized.push({
          title: paper.title.substring(0, 100),
          url: paper.url_abs || `https://paperswithcode.com/paper/${paper.id}`,
          description: (paper.abstract || '').substring(0, 120),
          source: 'Research Paper',
          points: 0
        });
      }
    }
  } else if (Array.isArray(data)) {
    for (const article of data) {
      if (article.title && article.url) {
        normalized.push({
          title: article.title.substring(0, 100),
          url: article.url,
          description: (article.description || '').substring(0, 120),
          source: 'DEV.to',
          points: article.public_reactions_count || 0
        });
      }
    }
  } else if (data.title && data.url && data.tag_list !== undefined) {
    normalized.push({
      title: data.title.substring(0, 100),
      url: data.url,
      description: (data.description || '').substring(0, 120),
      source: 'DEV.to',
      points: data.public_reactions_count || 0
    });
  }
}

const seen = new Set();
const unique = [];
for (const item of normalized) {
  const key = item.url.toLowerCase().split('?')[0];
  if (!seen.has(key)) {
    seen.add(key);
    unique.push(item);
  }
}

const categorized = { ai_ml: [], cloud: [], ai_tools: [], web_dev: [] };

for (const item of unique) {
  const text = (item.title + ' ' + item.description).toLowerCase();
  let assigned = false;
  for (const [cat, keywords] of Object.entries(categories)) {
    const score = keywords.filter(kw => text.includes(kw)).length;
    if (score > 0) {
      categorized[cat].push({ ...item, score });
      assigned = true;
      break;
    }
  }
}

const result = {};
for (const [cat, articles] of Object.entries(categorized)) {
  const top = articles.sort((a, b) => b.score - a.score || b.points - a.points).slice(0, 2);
  if (top.length > 0) result[cat] = top;
}

if (Object.keys(result).length === 0) {
  throw new Error('No articles found. Check if source APIs are responding.');
}

return [{ json: { categorized: result } }];

const { categorized } = $input.first().json;

const today = new Date().toLocaleDateString('en-IN', {
  weekday: 'long',
  year: 'numeric',
  month: 'long',
  day: 'numeric'
});

const catLabels = {
  ai_ml: '🤖 AI & Machine Learning',
  cloud: '☁️ Cloud & DevOps',
  ai_tools: '🛠️ AI Tools',
  web_dev: '🌐 Web Development'
};

let msg = `📡 <b>AI Daily Digest</b>\n`;
msg += `📅 ${today}\n`;
msg += `──────────────────────\n\n`;

for (const [cat, articles] of Object.entries(categorized)) {
  if (!articles || articles.length === 0) continue;

  msg += `${catLabels[cat] || '🔹 ' + cat}\n\n`;

  for (const article of articles) {
    msg += `<b>${article.title}</b>\n`;
    if (article.description) {
      msg += `${article.description}\n`;
    }
    msg += `🔗 <a href="${article.url}">${article.source}</a>\n\n`;
  }

  msg += `──────────────────────\n\n`;
}

msg += `⚙️ <i>Generated by your AI Digest Bot</i>`;

// Split if over Telegram's 4096 char limit
const MAX = 4000;
const parts = [];

if (msg.length <= MAX) {
  parts.push(msg);
} else {
  const chunks = msg.split('──────────────────────\n\n');
  let current = '';
  for (const chunk of chunks) {
    if ((current + chunk).length > MAX) {
      if (current) parts.push(current);
      current = chunk;
    } else {
      current += chunk + '──────────────────────\n\n';
    }
  }
  if (current) parts.push(current);
}

return parts.map((part, i) => ({
  json: { message: part, part: i + 1, total: parts.length }
}));
